pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        // Deploy a token that reverts if `from` is not the expected caller.
        TokenRevertIfFromNotCaller token = new TokenRevertIfFromNotCaller();
        bool ok;
        try c.transfer(from, address(token), _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract TokenRevertIfFromNotCaller {
    fallback() external payable {
        // abi.decode the `from` parameter of transferFrom
        (address from,,) = abi.decode(msg.data[4:], (address, address, uint256));
        require(from == msg.sender, "from != msg.sender");
    }
}

